import z3

def solve_sgp(g, s, w):
    n = g * s
    solver = z3.Solver()

    # X[week][golfer] = group
    X = [[z3.Int(f"x_{i}_{j}") for j in range(n)] for i in range(w)]

    for i in range(w):
        for j in range(n):
            solver.add(X[i][j] >= 0, X[i][j] < g)

    # Each group has exactly s golfers
    for i in range(w):
        for k in range(g):
            solver.add(z3.PbEq([(X[i][j] == k, 1) for j in range(n)], s))

    # No two golfers in the same group more than once
    for j1 in range(n):
        for j2 in range(j1 + 1, n):
            # Sum of (X[i][j1] == X[i][j2]) <= 1
            solver.add(z3.PbLe([(X[i][j1] == X[i][j2], 1) for i in range(w)], 1))

    # Symmetry breaking
    # Week 0: golfer j is in group j // s
    for j in range(n):
        solver.add(X[0][j] == j // s)

    # Week 1: first golfer of each group in week 0 are in group 0, 1, ..., g-1
    for k in range(g):
        solver.add(X[1][k * s] == k)

    print("Solving...")
    if solver.check() == z3.sat:
        m = solver.model()
        res = []
        for i in range(w):
            for j in range(n):
                res.append(m.evaluate(X[i][j]).as_long())
        print("SAT")
        print(res)
    else:
        print("UNSAT")

