import time
from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType

def solve_sgp_pysat(g, s, w):
    n = g * s

    # Variables: x[week][golfer][group]
    def var(week, golfer, group):
        return week * n * g + golfer * g + group + 1

    solver = Glucose4()

    # Each golfer is in exactly one group per week
    for i in range(w):
        for j in range(n):
            vars_j = [var(i, j, k) for k in range(g)]
            solver.add_clause(vars_j)
            for k1 in range(g):
                for k2 in range(k1 + 1, g):
                    solver.add_clause([-var(i, j, k1), -var(i, j, k2)])

    # Each group has exactly s golfers
    for i in range(w):
        for k in range(g):
            vars_k = [var(i, j, k) for j in range(n)]
            cnf = CardEnc.equals(lits=vars_k, bound=s, vpool=None, encoding=EncType.seqcounter)
            for clause in cnf.clauses:
                solver.add_clause(clause)

    # No two golfers in the same group more than once
    # For each pair of golfers, they can be in the same group at most once across all weeks
    # Let y[j1][j2][week] be true if j1 and j2 are in the same group in week
    # y[j1][j2][week] <-> OR_k (x[week][j1][k] AND x[week][j2][k])
    # Actually, we can just say: for any two weeks w1, w2, and any group k1, k2,
    # j1 and j2 cannot be in k1 in w1 AND in k2 in w2.
    # This means: x[w1][j1][k1] AND x[w1][j2][k1] AND x[w2][j1][k2] -> NOT x[w2][j2][k2]
    # So: -x[w1][j1][k1] V -x[w1][j2][k1] V -x[w2][j1][k2] V -x[w2][j2][k2]

    for j1 in range(n):
        for j2 in range(j1 + 1, n):
            for w1 in range(w):
                for w2 in range(w1 + 1, w):
                    for k1 in range(g):
                        for k2 in range(g):
                            solver.add_clause([
                                -var(w1, j1, k1),
                                -var(w1, j2, k1),
                                -var(w2, j1, k2),
                                -var(w2, j2, k2)
                            ])

    # Symmetry breaking
    # Week 0: golfer j is in group j // s
    for j in range(n):
        solver.add_clause([var(0, j, j // s)])

    # Week 1: first golfer of each group in week 0 are in group 0, 1, ..., g-1
    for k in range(g):
        solver.add_clause([var(1, k * s, k)])

    # Golfer 1 in week 1 is in group 0
    solver.add_clause([var(1, 1, 0)])

    print("Solving...")
    start = time.time()
    if solver.solve():
        print("SAT", time.time() - start)
        model = solver.get_model()
        res = []
        for i in range(w):
            for j in range(n):
                for k in range(g):
                    if model[var(i, j, k) - 1] > 0:
                        res.append(k)
        print(res)
    else:
        print("UNSAT", time.time() - start)

